import { unstable_cache } from 'next/cache';
import { revalidateTag } from 'next/cache';
import { getAllProducts } from '@/lib/db';

const getCachedProducts = unstable_cache(
  async () => {
    return await getAllProducts();
  },
  ['products-list'],
  { tags: ['products'] }
);

export default async function Page() {
  const products = await getCachedProducts();
  const lastRendered = new Date().toLocaleTimeString();

  async function syncCatalog() {
    'use server';
    // Invalidate the cache for products.
    // We intentionally do not await the revalidation or call revalidatePath/redirect
    // to allow the user to continue working immediately.
    // The fresh data will be fetched in the background on the next request.
    revalidateTag('products');
  }

  return (
    <div className="p-8">
      <h1 className="text-2xl font-bold mb-4">Product Catalog</h1>
      <div className="flex justify-between items-center mb-6">
        <p className="text-gray-500">Last rendered: {lastRendered}</p>
        <form action={syncCatalog}>
          <button 
            type="submit"
            className="bg-blue-500 hover:bg-blue-600 text-white px-4 py-2 rounded"
          >
            Sync latest catalog
          </button>
        </form>
      </div>

      <div className="border rounded-lg overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-gray-100">
            <tr>
              <th className="p-4 border-b">ID</th>
              <th className="p-4 border-b">Name</th>
              <th className="p-4 border-b">Price</th>
            </tr>
          </thead>
          <tbody>
            {products.map((p: any) => (
              <tr key={p.id} className="hover:bg-gray-50">
                <td className="p-4 border-b">{p.id}</td>
                <td className="p-4 border-b">{p.name}</td>
                <td className="p-4 border-b">${p.price}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

